#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K, T;
    if (!(cin >> K >> T)) return 0;
    vector<int> S(K + 1);
    for (int i = 1; i <= K; ++i) cin >> S[i];

    // Find nodes that are in cycles using indegree pruning (Kahn)
    vector<int> indeg(K + 1, 0);
    for (int i = 1; i <= K; ++i) indeg[S[i]]++;
    vector<char> inCycle(K + 1, 1);
    queue<int> q;
    for (int i = 1; i <= K; ++i) if (indeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inCycle[u] = 0;
        int v = S[u];
        if (--indeg[v] == 0) q.push(v);
    }

    // Assign cycle IDs
    vector<int> cycleId(K + 1, -1);
    vector<vector<int>> cycles;
    int cid = 0;
    for (int i = 1; i <= K; ++i) {
        if (inCycle[i] && cycleId[i] == -1) {
            vector<int> cyc;
            int v = i;
            do {
                cycleId[v] = cid;
                cyc.push_back(v);
                v = S[v];
            } while (v != i);
            cycles.push_back(move(cyc));
            cid++;
        }
    }

    // Build subordinate lists and filtered children (excluding intra-cycle edges)
    vector<vector<int>> subs(K + 1), children(K + 1);
    for (int y = 1; y <= K; ++y) subs[S[y]].push_back(y);
    for (int x = 1; x <= K; ++i) {} // prevent accidental misuse

    for (int x = 1; x <= K; ++x) {
        for (int y : subs[x]) {
            if (cycleId[x] != -1 && cycleId[y] == cycleId[x]) continue; // exclude cycle-internal child
            children[x].push_back(y);
        }
    }

    // Parent in the forest (excluding intra-cycle edges)
    vector<int> parent(K + 1, -1);
    for (int y = 1; y <= K; ++y) {
        if (cycleId[y] != -1 && cycleId[y] == cycleId[S[y]]) parent[y] = -1;
        else parent[y] = S[y];
    }

    // Pending children count for Kahn over forest
    vector<int> pending(K + 1, 0);
    for (int x = 1; x <= K; ++x) pending[x] = (int)children[x].size();

    // DP arrays: exact[x][g] = #assignments on T_x with g_x = g
    //            atmost[x][g] = sum_{h=1..g} exact[x][h]
    vector<vector<int>> exact(K + 1, vector<int>(T + 1, 0));
    vector<vector<int>> atmost(K + 1, vector<int>(T + 1, 0));

    queue<int> q2;
    for (int x = 1; x <= K; ++x) if (pending[x] == 0) q2.push(x);

    while (!q2.empty()) {
        int x = q2.front(); q2.pop();

        // Initialize exact[x] = 1 for all g
        for (int g = 1; g <= T; ++g) exact[x][g] = 1;

        // Multiply contributions from children (use atmost[child])
        for (int y : children[x]) {
            for (int g = 1; g <= T; ++g) {
                exact[x][g] = (int)((1LL * exact[x][g] * atmost[y][g]) % MOD);
            }
        }

        // Build atmost[x] as prefix sums of exact[x]
        int pref = 0;
        atmost[x][0] = 0;
        for (int g = 1; g <= T; ++g) {
            pref += exact[x][g];
            if (pref >= MOD) pref -= MOD;
            atmost[x][g] = pref;
        }

        int p = parent[x];
        if (p != -1) {
            if (--pending[p] == 0) q2.push(p);
        }
    }

    // Combine over cycles: for each cycle, sum over G of product of exact[u][G] for u in cycle
    long long ans = 1;
    for (const auto& cyc : cycles) {
        long long sumG = 0;
        for (int g = 1; g <= T; ++g) {
            long long prod = 1;
            for (int u : cyc) {
                prod = (prod * exact[u][g]) % MOD;
            }
            sumG += prod;
            if (sumG >= MOD) sumG -= MOD;
        }
        ans = (ans * sumG) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
