Solution idea:
- Treat lockers as nodes of a graph. Each constraint C_u XOR C_v = W is an edge (u, v, W).
- Use a weighted DSU (union-find) with XOR potentials:
  - For each node x, store xorToParent[x] = XOR from x to its set representative.
  - When unifying u and v with constraint w, if they are already in the same set, check that xor(u to rep) XOR xor(v to rep) equals w; otherwise it's impossible.
  - If they are in different sets, attach one root to the other and set xorToParent of the attached root to satisfy the new constraint.
- If constraints are consistent, for each connected component the set of valid assignments is C_j = t_comp XOR d[j], where d[j] is the XOR from j to a fixed root of that component, and t_comp is a free non-negative integer shared by the whole component.
- To minimize the sum over a component, choose each bit of t_comp independently so that the number of 1-bits in d[j] XOR t_comp at that bit is minimized. Thus, for each bit, set it in t_comp if the majority of d[j] have 1 at that bit; otherwise leave it 0.

This yields a globally minimal sum.

C++17 implementation:

```cpp
#include <bits/stdc++.h>
using namespace std;

struct XOR_DSU {
    int n;
    vector<int> parent, sz;
    vector<unsigned int> x; // xor to parent

    XOR_DSU(int n): n(n), parent(n), sz(n,1), x(n,0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int a) {
        if (parent[a] == a) return a;
        int p = parent[a];
        int r = find(p);
        x[a] ^= x[p];
        parent[a] = r;
        return r;
    }

    // returns xor from a to its representative
    unsigned int weight(int a) {
        find(a);
        return x[a];
    }

    // enforce val[u] XOR val[v] = w; return false if contradiction
    bool unite(int u, int v, unsigned int w) {
        int ru = find(u);
        int rv = find(v);
        unsigned int wu = x[u];
        unsigned int wv = x[v];
        if (ru == rv) {
            return ((wu ^ wv) == w);
        }
        if (sz[ru] < sz[rv]) {
            swap(ru, rv);
            swap(u, v);
            swap(wu, wv);
        }
        parent[rv] = ru;
        // Set xor from rv to ru so that constraint on (u,v) holds
        x[rv] = wu ^ w ^ wv;
        sz[ru] += sz[rv];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int K, L;
    if (!(cin >> K >> L)) return 0;
    vector<int> U(L), V(L);
    vector<unsigned int> W(L);
    for (int i = 0; i < L; ++i) {
        int u, v;
        unsigned int w;
        cin >> u >> v >> w;
        U[i] = u - 1;
        V[i] = v - 1;
        W[i] = w;
    }

    XOR_DSU dsu(K);
    for (int i = 0; i < L; ++i) {
        if (!dsu.unite(U[i], V[i], W[i])) {
            cout << -1 << '\n';
            return 0;
        }
    }

    // Gather components
    vector<int> root(K);
    vector<unsigned int> d(K);
    for (int i = 0; i < K; ++i) {
        root[i] = dsu.find(i);
        d[i] = dsu.weight(i);
    }
    vector<vector<int>> comps(K);
    for (int i = 0; i < K; ++i) comps[root[i]].push_back(i);

    const int BITS = 31; // enough since W <= 1e9 < 2^30
    vector<unsigned int> t_of_root(K, 0);
    for (int r = 0; r < K; ++r) {
        if (comps[r].empty()) continue;
        unsigned int t = 0;
        int n = (int)comps[r].size();
        for (int b = 0; b < BITS; ++b) {
            int cnt1 = 0;
            for (int idx : comps[r]) {
                if ((d[idx] >> b) & 1U) ++cnt1;
            }
            if (cnt1 > n - cnt1) t |= (1U << b);
        }
        t_of_root[r] = t;
    }

    vector<unsigned int> C(K);
    for (int i = 0; i < K; ++i) {
        C[i] = d[i] ^ t_of_root[root[i]];
    }

    for (int i = 0; i < K; ++i) {
        if (i) cout << ' ';
        cout << C[i];
    }
    cout << '\n';
    return 0;
}
```

Notes:
- If constraints are inconsistent, the DSU check detects it and prints -1.
- Otherwise, this constructs a valid assignment with minimal total sum by choosing the best per-component offset t bitwise.

Idea:
M is splendid iff it is even and its odd part is a perfect square. Equivalently, M can be written uniquely as M = 2^t · r^2 with t ≥ 1 and r odd. For each fixed t, the number of valid r is the number of odd r such that r^2 ≤ K / 2^t, which equals (floor(sqrt(K / 2^t)) + 1) // 2. Summing this over t = 1, 2, … while 2^t ≤ K gives the answer. Only about 60 terms are needed since K ≤ 1e18.

C++17 implementation:

```cpp
#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using u128 = __uint128_t;

static inline ull isqrt(ull n) {
    ull x = sqrtl((long double)n);
    while (x * x > n) --x;
    while ((x + 1) * (x + 1) <= n) ++x;
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ull K;
    if (!(cin >> K)) return 0;

    unsigned long long ans = 0;
    for (ull denom = 2; denom <= K; denom <<= 1) {  // denom = 2^t, t >= 1
        ull N = K / denom;
        if (N == 0) break;
        ull rmax = isqrt(N);
        ans += (rmax + 1) / 2;  // number of odd r in [1..rmax]
    }

    cout << ans << '\n';
    return 0;
}
```

This runs in O(log K) time and uses only 64-bit integers.

