Idea summary

- Let T1, …, TM be a valid list. Write Ti = di · ui, Ti+1 = di · vi with gcd(ui, vi) = 1 and ui · vi = Bi. In terms of prime exponents:
  - Let a_i(p) be the exponent of prime p in Ti.
  - Then |a_i(p) − a_{i+1}(p)| = v_p(Bi) for every i.
  - gcd(T1,…,TM) = 1 means min_i a_i(p) = 0 for every prime p.

- The total weight of a list is ∏i Ti = ∏p ∏i p^{a_i(p)}; so the weight is ∏p p^{sum_i a_i(p)}.
  Therefore the total sum of weights over all valid lists factorizes over primes:
  Answer = ∏p F_p, where F_p is the sum over all sequences (a_1(p),…,a_M(p)) with:
  - a_i ≥ 0
  - |a_i − a_{i+1}| = b_i(p) = v_p(Bi)
  - min_i a_i = 0
  of p^{sum_i a_i}.

- For a fixed prime p, define bi = v_p(Bi) and S = sum bi. Then all a_i(p) lie in [0, S]. We can DP along i = 1..M with states a_i ∈ [0..S], and a boolean “have we seen a zero yet?”.
  Transitions:
  - a_{i+1} ∈ {a_i + bi, a_i − bi} (the latter only if a_i ≥ bi)
  - when a_{i+1} = 0, the “zero seen” flag becomes true
  - weight multiplies by p^{a_{i+1}} at each step (since we accumulate sum of a_i)

- Complexity: For each prime p, O(M · S_p), where S_p = sum_i v_p(Bi). Since ∑p S_p = ∑i Ω(Bi) ≤ 9(M−1) (Ω = total number of prime factors with multiplicity), the total complexity is O(M · ∑i Ω(Bi)) ≤ about 9·10^6 in the worst case. This is fast enough.

- Primes not dividing any Bi contribute a factor 1, so we only process primes appearing in some Bi.

C++17 implementation

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD = 998244353LL;

    int M;
    if (!(cin >> M)) return 0;
    vector<int> B(M - 1);
    for (int i = 0; i < M - 1; ++i) cin >> B[i];

    // Sieve primes up to 1000
    const int MAXV = 1000;
    vector<int> primes;
    vector<bool> is_prime(MAXV + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i <= MAXV; ++i) {
        if (is_prime[i]) {
            primes.push_back(i);
            if (1LL * i * i <= MAXV)
                for (long long j = 1LL * i * i; j <= MAXV; j += i)
                    is_prime[(int)j] = false;
        }
    }

    long long answer = 1;

    // Process each prime that appears in any B[i]
    for (int p : primes) {
        // Compute bi = v_p(Bi) for all i
        int S = 0;
        int n = M - 1;
        vector<int> bi(n);
        bool hasAny = false;
        for (int i = 0; i < n; ++i) {
            int t = B[i];
            int cnt = 0;
            while (t > 0 && t % p == 0) {
                t /= p;
                ++cnt;
            }
            bi[i] = cnt;
            if (cnt > 0) {
                hasAny = true;
                S += cnt;
            }
        }

        if (!hasAny) continue; // this prime contributes 1

        // Precompute p^k for k = 0..S
        vector<long long> powP(S + 1, 1);
        for (int k = 1; k <= S; ++k) powP[k] = (powP[k - 1] * p) % MOD;

        // DP arrays: dp0[x] = ways with current a_i = x and zero not yet seen
        //            dp1[x] = ways with current a_i = x and zero already seen
        vector<long long> dp0(S + 1, 0), dp1(S + 1, 0);

        // Initialize for i = 1: a_1 = x in [0..S]
        for (int x = 0; x <= S; ++x) {
            long long val = powP[x]; // weight contribution so far is p^x
            if (x == 0) {
                dp1[0] = (dp1[0] + val) % MOD; // zero already seen at a1
            } else {
                dp0[x] = (dp0[x] + val) % MOD;
            }
        }

        // Transitions for i = 1..M-1 (total M-1 steps)
        for (int i = 0; i < M - 1; ++i) {
            int bcur = bi[i];
            vector<long long> ndp0(S + 1, 0), ndp1(S + 1, 0);

            for (int x = 0; x <= S; ++x) {
                long long v0 = dp0[x];
                if (v0) {
                    int y1 = x + bcur;
                    if (y1 <= S) {
                        ndp0[y1] = (ndp0[y1] + v0 * powP[y1]) % MOD;
                    }
                    if (x >= bcur) {
                        int y2 = x - bcur;
                        long long add = (v0 * powP[y2]) % MOD;
                        if (y2 == 0) {
                            ndp1[0] = (ndp1[0] + add) % MOD;
                        } else {
                            ndp0[y2] = (ndp0[y2] + add) % MOD;
                        }
                    }
                }
                long long v1 = dp1[x];
                if (v1) {
                    int y1 = x + bcur;
                    if (y1 <= S) {
                        ndp1[y1] = (ndp1[y1] + v1 * powP[y1]) % MOD;
                    }
                    if (x >= bcur) {
                        int y2 = x - bcur;
                        long long add = (v1 * powP[y2]) % MOD;
                        ndp1[y2] = (ndp1[y2] + add) % MOD;
                    }
                }
            }

            dp0.swap(ndp0);
            dp1.swap(ndp1);
        }

        long long Fp = 0;
        for (int x = 0; x <= S; ++x) {
            Fp = (Fp + dp1[x]) % MOD;
        }

        answer = (answer * Fp) % MOD;
    }

    cout << answer % MOD << "\n";
    return 0;
}
