        W[i] = w;
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }

    const int MAXB = 30; // since W_i < 2^30
    vector<long long> ans(K, 0);
    vector<int> val(K, -1);

    bool ok = true;
    for (int b = 0; b < MAXB && ok; ++b) {
        fill(val.begin(), val.end(), -1);
        for (int i = 0; i < K && ok; ++i) {
            if (val[i] != -1) continue;
            // Explore a new component with root value 0
            vector<int> comp;
            vector<int> st;
            val[i] = 0;
            st.push_back(i);
            while (!st.empty() && ok) {
                int u = st.back(); st.pop_back();
                comp.push_back(u);
                for (auto &e : adj[u]) {
                    int to = e.first;
                    int ei = e.second;
                    int bit = (W[ei] >> b) & 1;
                    int want = val[u] ^ bit;
                    if (val[to] == -1) {
                        val[to] = want;
                        st.push_back(to);
                    } else if (val[to] != want) {
                        ok = false;
                        break;
                    }
                }
            }
            if (!ok) break;
            int s = 0;
            for (int vtx : comp) s += val[vtx];
            int sz = (int)comp.size();
            bool flip = (s > sz - s);
            if (flip) {
                for (int vtx : comp) val[vtx] ^= 1;
            }
            for (int vtx : comp) {
                if (val[vtx] == 1) {
                    ans[vtx] |= (1LL << b);
                }
            }
        }
    }

    if (!ok) {
        cout << -1 << "\n";
        return 0;
    }

    for (int i = 0; i < K; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << "\n";
    return 0;
}
```

This program follows the described approach and outputs -1 if no valid assignment exists; otherwise it prints a valid assignment with the minimum possible total sum.

Idea:
A splendid number M must satisfy M = 2^p * q^2 with p ≥ 1 and q ≥ 1. Write M in the form M = 2^a * t where t is odd. Then t must be a perfect square, say t = s^2 with s odd. Each splendid M corresponds uniquely to a pair (p, s) with p ≥ 1, s odd, and M = 2^p * s^2.

For a fixed p, s^2 ≤ K / 2^p. Let div = floor(K / 2^p) = K >> p. Then the number of odd s with s^2 ≤ div equals the number of odd numbers ≤ floor(sqrt(div)), which is (floor(sqrt(div)) + 1) / 2.

Thus the total count is:
sum over p ≥ 1 of ( floor(sqrt(K >> p)) + 1 ) / 2, stopping when K >> p = 0.

We can compute this in O(log K) time (about 60 iterations). We just need an integer square root function that is exact.

C++17 implementation:

```cpp
#include <bits/stdc++.h>
using namespace std;

static unsigned long long isqrt(unsigned long long x) {
    unsigned long long r = sqrt((long double)x);
    while ((__int128)(r + 1) * (r + 1) <= x) ++r;
    while ((__int128)r * r > x) --r;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long K;
    if (!(cin >> K)) return 0;

    unsigned long long ans = 0;
    for (int p = 1; p < 64; ++p) {
        unsigned long long div = K >> p;
        if (div == 0) break;
        unsigned long long t = isqrt(div);
        ans += (t + 1) / 2;
    }

    cout << ans << "\n";
    return 0;
}
```

This matches the samples:
- K = 20 -> 5
- K = 400 -> 24
- K = 1234567890 -> 42413
